INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108401,1,0,'You must have went through some trouble to get your hands on this oak and ore.',12,0,100.0,1,0,66555,113870,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108401,2,0,'These are tricky materials to work with, but I think you\'ll be impressed with the final product.',12,0,100.0,1,0,66556,113874,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108401,3,0,'The weapons I\'m crafting should be sharp enough to pierce through any armor, and sturdy enough for repeated use.',12,0,100.0,1,0,66557,113876,0,'LegionCore');
